// onchain-verify — render the daily health report.
// Judged per metric on the metric's OWN clock (onchain.metrics.max_staleness_ms, migration 003).
// Every failing check NAMES its metrics: a bare count cannot be acted on, and could not be told
// apart from the permanent floor the old one-threshold-for-everything check produced (L-3).
const r = $('Verify query').first().json;
// The pulse comes from `Pulse query`, not from `r` — different database since the WI-62 move
// (task 015-33). Both `alert_last_ts` and `now_ms` come from THAT node: subtracting a `now_ms`
// read on the other container would be a difference between two clocks, and the report could
// not show it, because both values look like ordinary epoch-ms.
const q = $('Pulse query').first().json;
const p = $('Set Parameters').first().json;
const num = (x) => Number(x || 0);

const stale = num(r.stale_metrics);
const never = num(r.never_seen_metrics);
const unbounded = num(r.unbounded_metrics);
const orphans = num(r.orphans);
// A derived metric is HEALED, not healthy: the series has no gap, but a vendor stopped sending a
// field and someone must either chase that or retire the metric. Unlike L-3's permanent floor this
// is a real, closable condition, so it belongs in `ok` rather than being reported as background.
const derived = num(r.derived_metrics);

// WI-64 — the alert channel's own pulse.
//
// Every CONFIRMED Telegram delivery writes an `alert.delivered` row into onchain.diagnostics: this
// workflow's own daily report is the REGULAR one, onchain-error-alert's sends are the extra ones.
// That is what makes silence distinguishable from quiet — a week with no incidents still produces
// one row a day, so a missing row means the channel did not get out rather than "nothing happened".
// L-21: nine alerts failed across five days and nothing said so, because the reporter cannot report
// its own silence.
//
// The bound lives in Set Parameters and never here (L-3: a threshold inside the renderer is a
// threshold nobody can change without editing logic). It must exceed one daily cycle, because the
// query runs BEFORE today's report is sent and therefore reads the PREVIOUS cycle's row.
const channelBoundMs = Number(p.AlertHeartbeatMaxAgeMs);
const channelLastTs =
  q.alert_last_ts === null || q.alert_last_ts === undefined ? null : Number(q.alert_last_ts);
const channelAgeMs = channelLastTs === null ? null : num(q.now_ms) - channelLastTs;
// A missing bound and a missing row are BOTH defects, not "fine". A heartbeat nobody bounds is
// unmonitored, and "never delivered" is the state this check exists to name — it clears itself on
// the next run, because the report this very run sends writes the first row.
const channelUnbounded = !Number.isFinite(channelBoundMs) || channelBoundMs <= 0;
const channelSilent = channelUnbounded || channelAgeMs === null || channelAgeMs > channelBoundMs;
const hours = (ms) => Math.round(ms / 3600000);
const channelLine = channelUnbounded
  ? 'no AlertHeartbeatMaxAgeMs in Set Parameters — unmonitored'
  : channelAgeMs === null
    ? 'no confirmed delivery on record'
    : hours(channelAgeMs) + 'h since last confirmed delivery (bound ' + hours(channelBoundMs) + 'h)';

const ok =
  stale === 0 && never === 0 && unbounded === 0 && orphans === 0 && derived === 0 && !channelSilent;

const lines = [
  (ok ? '✅' : '⚠️') + ' onchain-verify (daily)',
  'rows: ' + r.total_rows + ' · buckets: ' + r.buckets,
  'metrics: ' + r.metrics_seen + '/' + r.metrics_registered + ' seen',
  'latest: ' + r.latest_ts_utc + ' UTC',
  (channelSilent ? '📵 ' : '📡 ') + 'alert channel: ' + channelLine,
];
if (stale) lines.push('⏳ stale (age > registry bound): ' + r.stale_names);
if (never) lines.push('👻 registered but never written: ' + r.never_seen_names);
if (unbounded) lines.push('❓ no max_staleness_ms in registry: ' + r.unbounded_names);
if (derived) lines.push('🧮 derived — vendor field missing, value computed: ' + r.derived_names);
if (orphans) lines.push('🔗 orphan rows (asset/metric not in registry): ' + orphans);

// L-4: the Report node sends with parse_mode=HTML, so this text MUST be HTML-escaped. Metric ids
// are snake_case and every '_' is an italic delimiter under Telegram's Markdown modes — naming the
// offenders (the whole point of L-3) is what made an unescaped message a guaranteed 400
// "can't parse entities". '&' first, or it would double-escape the entities produced after it.
const esc = (s) => String(s)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

let text = esc(lines.join('\n'));

// Telegram hard-caps a message at 4096 chars and the name lists are DB-derived, so bound them.
// Truncate AFTER escaping, then drop a half-written entity at the cut — a trailing '&am' would
// itself be an unparseable entity, i.e. the exact failure this guard exists to avoid.
if (text.length > 3500) {
  text = text.slice(0, 3500).replace(/&[a-z]{0,5}$/i, '') + '\n… truncated';
}

return [{ json: { ok, text } }];

// WI-64 — one `alert.delivered` row per CONFIRMED Telegram delivery.
//
// WHY THE ROW EXISTS. `onchain-error-alert` is the terminal reader for every health signal this
// project produces — the snapshotter's `Check dropped`, this workflow's report, onchain-retention's
// `Check outcomes` — and it is the one workflow whose own failure it cannot report, because it IS
// the reporter. L-21 recorded nine undelivered alerts across five days, noticed by accident during
// an unrelated acceptance. The cause was mundane (the laptop hosting the VM had no internet), and
// that is exactly why the gap is worth closing: the same silence recurs on causes nobody calls a
// defect.
//
// WHY IT IS CHAINED AFTER THE SEND, not fanned out beside it. An edge, not a canvas position: this
// node runs only when the Telegram node returned success, so the row means "Telegram accepted the
// message" and nothing weaker. L-4's rule — a monitoring change is proven by the message arriving,
// never by a query returning the right rows.
//
// WHY THE DATABASE AND NOT A SECOND ALERT. The DB is on the same VM and needs no egress, so it
// stays reachable exactly when the outbound path does not. A second Telegram channel with no
// heartbeat of its own would be two silences instead of one.
//
// WHY THIS WORKFLOW WRITES ONE AT ALL, when the record that filed WI-64 proposed writing only from
// onchain-error-alert: that handler runs only when something failed, so its rows alone cannot tell
// "no incidents" from "channel dead". The DAILY report is the regular pulse; the handler's sends
// are the extra ones.
const now = Date.now();

// ULID as TEXT (DB-SCHEMA §1.3) — the app generates the id. `onchain.diagnostics.id` carries no
// default, unlike `onchain.snapshots.id`. Same construction as onchain-retention's `Pass event`.
const B32 = '0123456789ABCDEFGHJKMNPQRSTVWXYZ';
let time = '';
let rest = now;
for (let i = 0; i < 10; i += 1) { time = B32[rest % 32] + time; rest = Math.floor(rest / 32); }
let rand = '';
for (let i = 0; i < 16; i += 1) rand += B32[Math.floor(Math.random() * 32)];

const event = {
  id: time + rand,
  ts: now,
  // `info`: a delivery that worked is not a warning. The signal is the ABSENCE of these rows, and
  // that absence is read by this workflow against the bound in its Set Parameters node.
  severity: 'info',
  event: 'alert.delivered',
  // The chat id is deliberately NOT recorded: it identifies a real person, which is the same reason
  // `export.sh` scrubs it out of the workflow JSON.
  detail_json: JSON.stringify({ workflow: 'onchain-verify', channel: 'telegram' }),
  created_at: now,
};

// Base64, bound as ONE `$1` parameter downstream: `queryReplacement` is positional CSV, so a value
// holding a comma breaks it and an empty value silently shifts every later `$N`. Base64 has
// neither, and it is driver-bound rather than interpolated.
return [{ json: { event_b64: Buffer.from(JSON.stringify([event])).toString('base64') } }];
